# parse extrusion points AND chain info (consecutive E moves)
raw=[]
with open('text.gcode') as f:
    for i,line in enumerate(f,1):
        if i < 15014 or i >= 98473: continue
        m=re.match(r'G[01]\s+(.*)', line.strip())
        if not m: continue
        x=y=e=None
        for tok in m.group(1).split():
            if tok.startswith('X'): x=float(tok[1:])
            elif tok.startswith('Y'): y=float(tok[1:])
            elif tok.startswith('E'): e=float(tok[1:])
        if x is not None and y is not None:
            raw.append((x,y,e))
# build chains of consecutive moves with E present (no travel gaps)
chains=[]; cur=[]
for x,y,e in raw:
    if e is not None:
        cur.append((x,y))
    else:
        if len(cur)>=2: chains.append(cur)
        cur=[]
if len(cur)>=2: chains.append(cur)
# rotate all points
pts=[]
for x,y in raw:
    if y is None: continue
    pts.append((x,y))
n=len(pts); sx=sum(x for x,y in pts); sy=sum(y for x,y in pts)
sxx=sum(x*x for x,y in pts); sxy=sum(x*y for x,y in pts)
b=(n*sxy-sx*sy)/(n*sxx-sx*sx); cx=sx/n; cy=sy/n
th=math.atan(b)
cos,sin=math.cos(th),math.sin(th)
def rot(x,y):
    return ((x-cx)*cos+(y-cy)*sin, -(x-cx)*sin+(y-cy)*cos)
# sample points on chains within window after rotation
X0,X1=-75.5,-17.0
Y0,Y1=-7.0,7.0
sam=set()
for c in chains:
    for (x1,y1),(x2,y2) in zip(c,c[1:]):
        rx1,ry1=rot(x1,y1); rx2,ry2=rot(x2,y2)
        if not (min(rx1,rx2)<=X1 and max(rx1,rx2)>=X0): continue
        d=math.hypot(x2-x1,y2-y1)
        nsteps=int(d/0.12)+1
        for j in range(nsteps+1):
            t=j/nsteps
            xx=x1+(x2-x1)*t; yy=y1+(y2-y1)*t
            rx,ry=rot(xx,yy)
            if X0<=rx<=X1 and Y0<=ry<=Y1:
                sam.add((rx,ry))
print('samples',len(sam))
# render
cell=0.15
cols=round((X1-X0)/cell); rows=round((Y1-Y0)/cell)
grid=[[' ']*cols for _ in range(rows)]
for rx,ry in sam:
    c=int((rx-X0)/cell); r=int((Y1-ry)/cell)
    if 0<=c<cols and 0<=r<rows: grid[r][c]='#'
with open('/tmp/word1.txt','w') as out:
    for r in range(rows):
        out.write(f'{r:3d} '+''.join(grid[r]).rstrip()+'\n')
print('saved',cols,rows)
